#pragma once

#include <stddef.h>
#include <stdint.h>

/* PET_BUILTIN_COUNT and PET_BUILTIN_DEFAULT (the first id of pets/builtin.txt,
 * also the fallback for a stored pet that does not load); generated by
 * tools/petpack.py builtins into the build directory. */
#include "pet_builtins.h"

typedef struct {
    const char *id;
    const uint8_t *bytes;
    size_t len;
} pet_builtin_t;

/** The packs compiled into the firmware, in pets/builtin.txt order (generated pet_builtins.c). */
extern const pet_builtin_t pet_builtins[PET_BUILTIN_COUNT];

/** Built-in i (0..PET_BUILTIN_COUNT-1, the default first), NULL past the end. */
const pet_builtin_t *pet_builtin_at(unsigned i);

/** The built-in with this id, NULL when the id is not a built-in. */
const pet_builtin_t *pet_builtin_find(const char *id);
